function calculateLockerNumber(phone, totalLockers = 10) {
  let sum = 0;
  for (let i = 0; i < phone.length; i++) {
    sum += phone.charCodeAt(i);
  }
  return sum % totalLockers;
}

console.log("手机号 13800001111 分配到的柜子:", calculateLockerNumber('13800001111'));
console.log("手机号 13999992222 分配到的柜子:", calculateLockerNumber('13999992222'));
